import json
for line in open("run.jsonl"):
    try: e = json.loads(line)
    except ValueError: continue
    if e.get("type") == "system" and e.get("subtype") == "init":
        print("mcp servers:", e.get("mcp_servers")); print("pitchlist tools seen:", [t for t in e.get("tools", []) if "pitchlist" in t])
    if e.get("type") == "assistant":
        for b in e["message"]["content"]:
            if b["type"] == "tool_use": print("CALL", b["name"], json.dumps(b["input"])[:150])
    if e.get("type") == "user":
        for b in e["message"]["content"]:
            if isinstance(b, dict) and b.get("type") == "tool_result":
                c = b.get("content"); c = c if isinstance(c, str) else json.dumps(c)
                print("  ->", "ERROR" if b.get("is_error") else "ok", len(c), "chars")
    if e.get("type") == "result":
        print("\nturns:", e.get("num_turns"), "| seconds:", round(e.get("duration_ms", 0)/1000), "\n\nANSWER:\n" + (e.get("result") or "")[:2600])
EOF
head -c 400 run.err

